steps.run:
set -euo pipefail
tested_sha="$(git rev-parse HEAD)"
test "$tested_sha" = "$EXPECTED_SHA"
node --input-type=module <<'NODE'
import fs from 'node:fs';
import { getWorkerChangesBetween } from './scripts/worker-deploy-impact.mjs';
const workerDeploy = process.env.AUTO_WORKER_DEPLOY === 'true'
  ? await getWorkerChangesBetween(process.env.PUSH_BEFORE_SHA, process.env.EXPECTED_SHA)
  : { dataPlane: false, aiProxy: false };
const version = JSON.parse(fs.readFileSync('version.json', 'utf8')).version;
fs.mkdirSync('.release', { recursive: true });
fs.writeFileSync('.release/aio-release-attestation.json', JSON.stringify({
  schemaVersion: 'aio-release-attestation.v1',
  testedSha: process.env.EXPECTED_SHA,
  appRevision: version,
  origin: process.env.RELEASE_ORIGIN,
  runId: process.env.GITHUB_RUN_ID,
  repository: process.env.GITHUB_REPOSITORY,
  workerDeploy,
  attestedAt: new Date().toISOString()
}, null, 2) + '\n');
NODE

set -euo pipefail
if [ "$EVENT_NAME" = 'workflow_run' ]; then run_id="$WORKFLOW_RUN_ID"; expected_sha="$WORKFLOW_SHA"; else run_id="$DISPATCH_CI_RUN_ID"; expected_sha=''; fi
case "$run_id" in ''|null|*[!0-9]*) echo "::error::a successful CI run id is required"; exit 1;; esac
gh api "repos/$GITHUB_REPOSITORY/actions/runs/$run_id" --jq '[.name, .conclusion, (.head_branch // ""), (.head_sha // ""), (.event // ""), (.head_repository.full_name // "")] | @tsv' > "$RUNNER_TEMP/aio-worker-ci-run.tsv"
IFS="$(printf '\t')" read -r workflow_name conclusion branch ci_sha ci_event ci_repo < "$RUNNER_TEMP/aio-worker-ci-run.tsv"
[ "$workflow_name" = 'CI' ] || { echo "::error::run $run_id is '$workflow_name', expected CI"; exit 1; }
[ "$conclusion" = 'success' ] || { echo "::error::CI run $run_id concluded '$conclusion', expected success"; exit 1; }
[ "$branch" = 'main' ] || { echo "::error::CI run $run_id ran on '$branch', expected main"; exit 1; }
[ "$ci_event" = 'push' ] || { echo "::error::CI run $run_id was triggered by '$ci_event', expected a push to main"; exit 1; }
[ "$ci_repo" = "$GITHUB_REPOSITORY" ] || { echo "::error::CI run $run_id came from '$ci_repo', not $GITHUB_REPOSITORY (fork)"; exit 1; }
if [ -n "$expected_sha" ]; then [ "$ci_sha" = "$expected_sha" ] || { echo "::error::CI run SHA differs from workflow_run SHA"; exit 1; }; fi
[[ "$ci_sha" =~ ^[0-9a-f]{40}$ ]] || { echo "::error::CI run has invalid head SHA"; exit 1; }
echo "run_id=$run_id" >> "$GITHUB_OUTPUT"
echo "sha=$ci_sha" >> "$GITHUB_OUTPUT"

set -euo pipefail
node --input-type=module <<'NODE'
import fs from 'node:fs';
const file = `${process.env.RUNNER_TEMP}/aio-worker-attestation/aio-release-attestation.json`;
const attestation = JSON.parse(fs.readFileSync(file, 'utf8'));
if (attestation.schemaVersion !== 'aio-release-attestation.v1' || attestation.testedSha !== process.env.EXPECTED_SHA || String(attestation.runId) !== process.env.EXPECTED_RUN_ID || attestation.repository !== process.env.GITHUB_REPOSITORY) {
  throw new Error('CI attestation does not match the successful run SHA');
}
if (typeof attestation.workerDeploy?.aiProxy !== 'boolean') throw new Error('CI attestation has no AI-proxy change result');
fs.appendFileSync(process.env.GITHUB_OUTPUT, `sha=${attestation.testedSha}\nattested_change=${attestation.workerDeploy.aiProxy}\n`);
NODE

set -euo pipefail
health_status="$(curl --silent --show-error --output "$RUNNER_TEMP/aio-proxy-convergence-health.json" --write-out '%{http_code}' -H 'Origin: https://ysnle.github.io' "$AI_PROXY_URL/health" || true)"
if [ "$health_status" != '200' ] && [ "$health_status" != '503' ]; then echo "::error::cannot resolve AI proxy convergence: HTTP $health_status"; exit 1; fi
LIVE_SHA="$(node -e "const h=require(process.argv[1]);process.stdout.write(typeof h.sourceSha==='string'?h.sourceSha:'')" "$RUNNER_TEMP/aio-proxy-convergence-health.json")"
CURRENT_MAIN_SHA="$(gh api "repos/$GITHUB_REPOSITORY/branches/main" --jq '.commit.sha')"
export LIVE_SHA CURRENT_MAIN_SHA
# A newer main must exist locally to classify what it changed; an unreachable commit fails closed to the stale skip.
[[ "$CURRENT_MAIN_SHA" =~ ^[0-9a-f]{40}$ ]] && timeout 120 git fetch --no-tags --quiet origin "$CURRENT_MAIN_SHA" || true
node --input-type=module <<'NODE'
import fs from 'node:fs';
import { getMainAdvanceWorkerChanges, getWorkerChangesBetween, isAncestorCommit, shouldDeployWorker } from './scripts/worker-deploy-impact.mjs';
const manual = process.env.EVENT_NAME === 'workflow_dispatch';
const changed = process.env.ATTESTED_CHANGE === 'true';
const liveSha = process.env.LIVE_SHA;
// P1351: a main that only gained data-refresh commits still carries the tested Worker bytes.
const newerMainChanges = process.env.CURRENT_MAIN_SHA === process.env.EXPECTED_SHA ? undefined : getMainAdvanceWorkerChanges(process.env.EXPECTED_SHA, process.env.CURRENT_MAIN_SHA);
const mainAdvanceSafe = process.env.CURRENT_MAIN_SHA === process.env.EXPECTED_SHA || newerMainChanges?.aiProxy === false;
const liveIsAncestor = !manual && mainAdvanceSafe
  && liveSha !== process.env.EXPECTED_SHA && /^[0-9a-f]{40}$/.test(liveSha)
  && isAncestorCommit(liveSha, process.env.EXPECTED_SHA);
const cumulativeChanges = liveIsAncestor && !changed
  ? await getWorkerChangesBetween(liveSha, process.env.EXPECTED_SHA)
  : undefined;
const shouldDeploy = shouldDeployWorker({ plane: 'aiProxy', manual, attestedChanged: changed, liveSha, testedSha: process.env.EXPECTED_SHA, latestMainSha: process.env.CURRENT_MAIN_SHA, cumulativeChanges, newerMainChanges });
fs.appendFileSync(process.env.GITHUB_OUTPUT, `should_deploy=${shouldDeploy}\n`);
const reason = !manual && process.env.CURRENT_MAIN_SHA !== process.env.EXPECTED_SHA && !mainAdvanceSafe ? 'stale-ci-run' : shouldDeploy ? 'worker-change-or-live-drift' : 'already-converged-or-no-worker-change';
fs.appendFileSync(process.env.GITHUB_OUTPUT, `reason=${reason}\n`);
console.log(`AI-proxy automatic convergence decision: ${shouldDeploy ? 'deploy' : 'skip'} (live=${liveSha || 'unknown'}, tested=${process.env.EXPECTED_SHA})`);
NODE

