health_status="$(curl --silent --show-error --output "$RUNNER_TEMP/aio-fast-convergence-health.json" --write-out '%{http_code}' "$FAST_QUOTES_URL/health" || true)"
if [ "$health_status" != '200' ] && [ "$health_status" != '503' ]; then echo "::error::cannot resolve fast data-plane convergence: HTTP $health_status"; exit 1; fi
