import fs from 'node:fs';
import { getMainAdvanceWorkerChanges, getWorkerChangesBetween, isAncestorCommit, shouldDeployWorker } from './scripts/worker-deploy-impact.mjs';
const manual = process.env.EVENT_NAME === 'workflow_dispatch';
const changed = process.env.ATTESTED_CHANGE === 'true';
const liveSha = process.env.LIVE_SHA;
