  ? await getWorkerChangesBetween(liveSha, process.env.EXPECTED_SHA)
  : undefined;
const dispatchRepair = mainAdvanceSafe && process.env.DISPATCH_MISSING === 'true' && process.env.HAS_DISPATCH_SECRET === 'true';
const shouldDeploy = dispatchRepair || shouldDeployWorker({ plane: 'dataPlane', manual, attestedChanged: changed, liveSha, testedSha: process.env.EXPECTED_SHA, latestMainSha: process.env.CURRENT_MAIN_SHA, cumulativeChanges, newerMainChanges });
fs.appendFileSync(process.env.GITHUB_OUTPUT, `should_deploy=${shouldDeploy}\n`);
