node --input-type=module - <<'NODE'
import fs from 'node:fs';
import { marketAnalysisDiagnostic } from './scripts/lib/operational-health.mjs';
try {
  const d = JSON.parse(fs.readFileSync('public-data/data.json', 'utf8'));
  const m = d.meta || {};
   const ts = m.generatedAt ? new Date(m.generatedAt).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' }) : 'n/a';
   const generatedAtMs = Date.parse(m.generatedAt || '');
   const generatedStatus = Number.isFinite(generatedAtMs) ? 'OK' : 'WARN';
   const elapsedMs = Number(m.elapsedMs);
   const elapsedStatus = Number.isFinite(elapsedMs) && elapsedMs > 0 ? 'OK' : 'WARN';
   const totalSymbols = (m.symbolsOk || 0) + (m.symbolsFail || 0);
  const rows = [
    '| Layer | Status | Value |',
    '|------|------|-----|',
    `| Generated (KST) | ${generatedStatus} | ${ts} |`,
    `| Quotes | ${m.symbolsOk >= 70 ? 'OK' : 'WARN'} | ${m.symbolsOk || 0}/${totalSymbols} failed: ${(m.failedSymbols || []).join(',') || 'none'} |`,
    `| Twelve Data fallback | ${m.tdHasKey ? 'OK' : 'SKIP'} | hasKey=${m.tdHasKey} eligible=${m.tdFallbackEligible || 0} recovered=${m.tdFallbackRecovered || 0} |`,
    `| Fear&Greed | ${m.fearGreedOk ? 'OK' : 'WARN'} | ${d.fearGreed && d.fearGreed.score != null ? d.fearGreed.score : 'n/a'} |`,
    `| Cboe Put/Call | ${m.putCallOk ? 'OK (delayed)' : 'WARN'} | ${d.putCall && d.putCall.totalPutCall != null ? d.putCall.totalPutCall + ' · ' + (d.putCall.asOf || 'date n/a') : 'n/a'} |`,
    `| FRED Secret | ${m.fredHasKey ? (m.fredFailedSeries && m.fredFailedSeries.length ? 'WARN' : 'OK') : 'MISSING'} | fredFetchOk: ${m.fredFetchOk ? 'yes (' + (m.macroKeyCount || 0) + ' keys)' : 'no'}${m.fredFailedSeries && m.fredFailedSeries.length ? ' · failed: ' + m.fredFailedSeries.join(',') : ''} |`,
    `| FRED LKG | ${m.fredLkgUsed ? 'REFERENCE' : 'N/A'} | source=${m.fredLkgSource || 'none'} · original observation dates retained |`,
    `| BLS official | ${m.blsStatus === 'ok' || m.blsStatus === 'cached-fresh' ? 'OK' : m.blsStatus === 'partial' ? 'PARTIAL' : 'WARN'} | status=${m.blsStatus || 'unavailable'} series=${m.blsSeriesCount || 0}/6 failed=${(m.blsFailedSeries || []).join(',') || 'none'} lastSuccessfulAt=${m.blsLastSuccessfulAt || 'none'} |`,
    `| Treasury curve | ${m.treasuryStatus === 'ok' || m.treasuryStatus === 'cached-fresh' ? 'OK' : 'WARN'} | status=${m.treasuryStatus || 'unavailable'} observed=${m.treasuryObservedAt || 'none'} same-date 10Y-2Y only |`,
    `| AAII weekly | ${m.aaiiStatus === 'current-reference' ? 'REFERENCE' : 'WARN'} | observed=${m.aaiiObservedAt || 'none'} relay=${m.aaiiRelayUsed ? 'bounded-reader' : 'direct/none'} decisionUse=false |`,
    `| News | ${m.newsOk ? 'OK' : 'WARN'} | ${m.newsCount || 0} items · ${m.newsCycleLabel || 'cycle n/a'} |`,
    `| Lane quarantine | ${(m.laneQuarantine || []).length ? 'DEGRADED' : 'OK'} | ${(m.laneQuarantine || []).map((e) => `${e.lane} ${e.remedy} since ${e.since}`).join(', ').replace(/[|\r\n]/g, ' ') || 'none'} |`,
    `| LLM Analysis | ${m.marketAnalysisOk ? 'OK' : 'WARN'} | ${m.marketAnalysisOk ? ((d.marketAnalysis && d.marketAnalysis.model) || 'model n/a') : marketAnalysisDiagnostic(d).replace(/[|\r\n]/g, ' ')} |`,
    `| Fundamentals | ${Number(m.fundamentalCoveragePct || 0) >= 80 ? 'OK' : 'PARTIAL'} | free SEC companyfacts=${m.secFundamentalsCount || 0} coverage=${m.fundamentalCoveragePct || 0}% · paid FMP not required |`,
    `| Elapsed | ${elapsedStatus} | ${Number.isFinite(elapsedMs) ? elapsedMs : 'n/a'}ms |`,
  ].join('\n');
  const summary = `## Data refresh summary\n\n${rows}\n`;
  fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY || '/dev/null', summary);
  console.log(summary);
 } catch(e) {
   console.error('summary generation failed:', e.message);
   process.exitCode = 1;
 }
